// Assemble an OCI image-layout archive (a plain tar) from a manifest, a config and layer blobs that were already fetched and
// digest-verified. The result is exactly the shape `image-archive.js` reads from a local `oci-archive`, so a remote image and a local
// one go through ONE parser and the same size and path guards. Nothing is extracted to disk.
import crypto from 'node:crypto';

const BLOCK = 512;

function octal(n, len) { return n.toString(8).padStart(len - 1, '0') + '\0'; }

/** A single ustar entry. Names here are generated by this module (`blobs/sha256/<hex>`), never taken from the network. */
function tarEntry(name, data) {
  if (Buffer.byteLength(name) > 100) throw new Error('tar entry name too long');
  const header = Buffer.alloc(BLOCK, 0);
  header.write(name, 0, 'utf8');
  header.write(octal(0o644, 8), 100);
  header.write(octal(0, 8), 108); header.write(octal(0, 8), 116);
  header.write(octal(data.length, 12), 124);
  header.write(octal(0, 12), 136);
  header.fill(0x20, 148, 156);
  header.write('0', 156);
  header.write('ustar\0', 257); header.write('00', 263);
  let sum = 0; for (const b of header) sum += b;
  header.write(octal(sum, 7), 148); header[155] = 0x20;
  const pad = (BLOCK - (data.length % BLOCK)) % BLOCK;
  return Buffer.concat([header, data, Buffer.alloc(pad, 0)]);
}

export const sha256Hex = (buf) => crypto.createHash('sha256').update(buf).digest('hex');

/**
 * @param {{manifest: Buffer, config: Buffer, layers: Buffer[]}} img  bytes exactly as the registry served them
 * @returns {{tar: Buffer, manifestDigest: string}}
 */
export function buildOciArchive({ manifest, config, layers, mediaType = 'application/vnd.oci.image.manifest.v1+json' }) {
  const manifestHex = sha256Hex(manifest);
  const index = Buffer.from(JSON.stringify({ schemaVersion: 2, manifests: [{ mediaType, digest: `sha256:${manifestHex}`, size: manifest.length }] }));
  const parts = [
    tarEntry('oci-layout', Buffer.from(JSON.stringify({ imageLayoutVersion: '1.0.0' }))),
    tarEntry('index.json', index),
    tarEntry(`blobs/sha256/${manifestHex}`, manifest),
    tarEntry(`blobs/sha256/${sha256Hex(config)}`, config),
  ];
  const seen = new Set([manifestHex, sha256Hex(config)]);
  for (const l of layers) { const h = sha256Hex(l); if (seen.has(h)) continue; seen.add(h); parts.push(tarEntry(`blobs/sha256/${h}`, l)); }
  parts.push(Buffer.alloc(BLOCK * 2, 0));
  return { tar: Buffer.concat(parts), manifestDigest: `sha256:${manifestHex}` };
}
